namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Interfaces.Rest.Resources;

/// <summary>
///     Resource representing an alert evaluated by an Edge Gateway. The first reading is the triggering reading; the
///     alert time is its capture time. Threshold alerts carry the evaluated range and geofence alerts the distance to
///     the boundary.
/// </summary>
/// <param name="AlertId">The alert identifier generated by the gateway.</param>
/// <param name="DeviceId">The device that captured the supporting readings.</param>
/// <param name="Type">The alert type: Temperature, Activity or Geofence.</param>
/// <param name="Severity">The alert severity: Informative, Warning or Critical.</param>
/// <param name="ReadingIds">The supporting readings.</param>
/// <param name="ConfigurationRevision">The rule revision used to evaluate the alert.</param>
/// <param name="ThresholdMinValue">The lower bound of the evaluated threshold.</param>
/// <param name="ThresholdMaxValue">The upper bound of the evaluated threshold.</param>
/// <param name="GeofenceId">The geofence that was left.</param>
/// <param name="DistanceToBoundaryMeters">The distance to the geofence boundary in meters.</param>
public record EdgeAlertResource(
    Guid AlertId,
    Guid DeviceId,
    string? Type,
    string? Severity,
    IReadOnlyList<Guid>? ReadingIds,
    long ConfigurationRevision,
    double? ThresholdMinValue,
    double? ThresholdMaxValue,
    Guid? GeofenceId,
    double? DistanceToBoundaryMeters);
